args.command:
python3 -c "
import chromadb
try:
    c = chromadb.PersistentClient(path='/root/.nanobot/workspace/memory_palace')
    col = c.get_collection('memory_palace')
    cnt = col.count()
    print(f'memory_palace collection: Total docs = {cnt}')
    if cnt > 0:
        p = col.peek(limit=min(cnt, 50))
        ids = p['ids']
        metas = p['metadatas'] if isinstance(p['metadatas'], list) else []
        dists = p.get('distances', None)
        print(f'Sample IDs ({len(ids)} shown): {ids[:5]}')
        if metas:
            keys_seen = {}
            for m in metas[:10]:
                for k,v in (m.items() if m else {}):
                    keys_seen[k] = True
            print(f'Metadata keys seen: {list(keys_seen.keys())}')
except Exception as e:
    print(f'ERROR accessing memory_palace collection: {e}')
"
